from pathlib import Path; import sys
for spec in sys.argv[1:]:
 name, start, end=spec.rsplit(":",2); lines=Path(name).read_text().splitlines()
 for n in range(int(start),min(int(end),len(lines))+1): print(f"{name}:{n}: {lines[n-1]}")

